package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TrackerUrlVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property tracker url of observed issue ")
  void test_tracker_url_v_o_builder() {
    Assertions.assertFalse(TrackerUrlVO.nullValue().getTrackerUrl().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(TrackerUrlVO.tryFrom(null).getTrackerUrl().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", TrackerUrlVO.from("one").getTrackerUrl().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> TrackerUrlVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", TrackerUrlVO.from("one").toString());
  }
}
